<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useAuth} from '../stores/auth'
import {query,binary,practicePath,filename,saveBlob,errorText} from '../api/client'
import {roles,notify} from '../composables/ui'
import DataTable from '../components/DataTable.vue'
import Detail from '../components/Detail.vue'
import Modal from '../components/Modal.vue'
const route=useRoute(),auth=useAuth(),project=ref(route.query.project==='repair'?'repair':'ticket'),tab=ref('users'),users=ref([]),identity=ref(''),rows=ref([]),busy=ref(false),error=ref(''),detail=ref(null),detailBusy=ref(false),related=ref(''),extra=ref(null),detailError=ref(''),previews=ref({}),scope=ref('ASSIGNED')
const tabs=computed(()=>project.value==='ticket'?[['users','模拟用户'],['activities','活动列表'],['records','票券记录']]:[['users','模拟用户'],['devices','设备列表'],['orders','工单列表']])
const availableUsers=computed(()=>users.value.filter(u=>u.status===1&&(project.value!=='ticket'||tab.value!=='records'||u.role==='USER')))
const selected=computed(()=>users.value.find(u=>String(u.id)===identity.value))
const columns=computed(()=>({users:['id','userNo','realName','role','status'],activities:['id','activityName','campus','quota','bookedCount','status'],records:['id','ticketNo','activityId','userId','status'],devices:['id','deviceName','deviceType','campus','status'],orders:['id','orderNo','title','reporterId','maintainerId','status']})[tab.value])
let seq=0,detailSeq=0
function clearDetail(){detailSeq++;detail.value=null;related.value='';extra.value=null;detailError.value='';for(const u of Object.values(previews.value))URL.revokeObjectURL(u);previews.value={}}
async function load(refreshUsers=false){const n=++seq;clearDetail();rows.value=[];busy.value=true;error.value='';const p=project.value,t=tab.value;try{
 if(refreshUsers||!users.value.length){const data=await query(p,'/users');if(n!==seq)return;users.value=data;if(!data.some(u=>String(u.id)===identity.value))identity.value=String(data.find(u=>u.status===1)?.id||'')}
 if(n!==seq)return
 if(t==='users')rows.value=users.value
 else if(t==='records'){if(selected.value?.role!=='USER')identity.value=String(users.value.find(u=>u.role==='USER'&&u.status===1)?.id||'');if(!identity.value)throw new Error('请先选择当前空间中的模拟用户。');const data=await query(p,`/users/${encodeURIComponent(identity.value)}/records`);if(n!==seq)return;rows.value=data}
 else {const data=await query(p,'/'+t,t==='orders'?{operatorId:identity.value,scope:selected.value?.role==='MAINTAINER'?scope.value:undefined}:undefined);if(n!==seq)return;rows.value=data}
 }catch(e){if(n===seq)error.value=errorText(e)}finally{if(n===seq)busy.value=false}}
async function changeProject(){seq++;users.value=[];identity.value='';rows.value=[];tab.value='users';await load(true)}
function selectTab(key){tab.value=key;if(key==='records'&&selected.value?.role!=='USER')identity.value=String(users.value.find(u=>u.role==='USER'&&u.status===1)?.id||'');load()}
async function changeIdentity(){clearDetail();rows.value=[];await load()}
async function show(row){const n=++detailSeq,p=project.value,t=tab.value;detailBusy.value=true;detailError.value='';try{const id=t==='users'&&p==='ticket'?row.userNo:row.id;const d=await query(p,`/${t}/${encodeURIComponent(id)}`,['records','orders'].includes(t)?{operatorId:identity.value}:undefined);if(n===detailSeq){detail.value=d;related.value='';extra.value=null}}catch(e){if(n===detailSeq)error.value=errorText(e)}finally{if(n===detailSeq)detailBusy.value=false}}
async function loadRelated(type){const n=++detailSeq;related.value=type;extra.value=null;detailError.value='';detailBusy.value=true;const order=detail.value.order||detail.value;try{const d=await query('repair',`/orders/${order.id}/${type}`,{operatorId:identity.value});if(n===detailSeq)extra.value=d}catch(e){if(n===detailSeq)detailError.value=errorText(e)}finally{if(n===detailSeq)detailBusy.value=false}}
async function imageAction(img,download=false){const generation=detailSeq;try{const id=img.imageId??img.id;const r=await binary(practicePath('repair',`/images/${id}/${download?'download':'preview'}`));if(download)saveBlob(r.data,filename(r.headers));else {if(generation!==detailSeq)return;if(previews.value[id])URL.revokeObjectURL(previews.value[id]);previews.value[id]=URL.createObjectURL(r.data)}}catch(e){notify(errorText(e),true)}}
function resetEvent(e){let d=e.detail;if(e.type==='storage'){if(e.key!==`practice:${auth.user?.userId}:reset-event`)return;try{d=JSON.parse(e.newValue)}catch{return}}if(d&&(d.project==='ALL'||d.project.toLowerCase()===project.value)){clearDetail();users.value=[];identity.value='';load(true)}}
onMounted(()=>{load(true);window.addEventListener('practice-reset',resetEvent);window.addEventListener('storage',resetEvent)})
onUnmounted(()=>{seq++;clearDetail();window.removeEventListener('practice-reset',resetEvent);window.removeEventListener('storage',resetEvent)})
watch(()=>route.query.project,v=>{if(v&&v!==project.value){project.value=v==='repair'?'repair':'ticket';changeProject()}})
</script>
<template><div class="section-heading"><div><h1>我的项目数据</h1><p>请先观察真实数据和状态。需要尝试业务操作时，请进入 <RouterLink to="/docs">接口文档</RouterLink>。</p></div><button class="secondary" :disabled="busy" @click="load(true)">{{busy?'正在刷新…':'刷新数据'}}</button></div><div class="project-switch"><button :class="{active:project==='ticket'}" @click="project='ticket';changeProject()">校园抢票</button><button :class="{active:project==='repair'}" @click="project='repair';changeProject()">校园报修</button></div><section class="panel"><div class="identity-bar"><label>项目模拟身份<select v-model="identity" @change="changeIdentity"><option value="">请选择模拟用户</option><option v-for="u in availableUsers" :key="u.id" :value="String(u.id)">{{u.realName||u.name||u.userNo}} · {{roles[u.role]}} · 数据库ID {{u.id}}</option></select></label><p v-if="project==='repair'">这是项目模拟身份，不是系统账号。{{selected?.role==='ADMIN'?'管理员可查询本空间全部工单。':selected?.role==='MAINTAINER'?'维修师傅可查询分派给本人或本人参与的工单。':'报修人仅可查询本人提交的工单。'}}</p><p v-else>模拟用户ID请从当前工作空间的用户列表中获取。票券列表展示所选模拟用户的记录。</p></div><div class="tabs"><button v-for="[key,name] in tabs" :key="key" :class="{active:tab===key}" @click="selectTab(key)">{{name}}</button></div><label v-if="tab==='orders'&&selected?.role==='MAINTAINER'" class="inline-field">查询范围<select v-model="scope" @change="load()"><option value="ASSIGNED">当前分派给我</option><option value="PARTICIPATED">我曾参与处理</option></select></label><div v-if="error" role="alert" class="alert error">{{error}}</div><p v-if="busy" role="status">正在查询当前空间的数据…</p><DataTable :rows="rows" :columns="columns" :kind="tab" actions><template #default="{row}"><button class="text-button" :disabled="detailBusy||busy" @click="show(row)">查看详情</button></template></DataTable></section><Modal v-if="detail" title="数据详情" @close="clearDetail"><Detail :value="detail" :kind="tab"/><template v-if="project==='repair'&&tab==='orders'"><div class="tabs"><button @click="loadRelated('process-records')">处理记录</button><button @click="loadRelated('images')">工单图片</button><button @click="loadRelated('evaluation')">工单评价</button></div><p v-if="detailBusy">正在读取…</p><div v-if="detailError" class="alert error">{{detailError}}</div><template v-if="extra"><template v-if="related==='images'"><p v-if="!extra.length" class="empty">该工单暂无图片。</p><div v-for="img in extra" :key="img.imageId??img.id" class="image-row"><span>{{img.originalFilename||img.originalName||'工单图片'}} · {{img.imageType===1?'故障图片':'维修图片'}}</span><button class="secondary" @click="imageAction(img)">预览</button><button class="secondary" @click="imageAction(img,true)">下载</button><img v-if="previews[img.imageId??img.id]" :src="previews[img.imageId??img.id]" alt="工单图片预览"></div></template><template v-else-if="Array.isArray(extra)"><p v-if="!extra.length" class="empty">暂无处理记录。</p><Detail v-for="(r,i) in extra" :key="i" :value="r"/></template><Detail v-else :value="extra"/></template></template></Modal></template>
